require_once __DIR__.'/../../../includes/certificate_generator.php';$q=trim($_GET['q']??'');$pt=$_GET['pt']??'all';$cond='';$params=[$currentSemesterId];if($q!==''){$cond.=' AND (u.full_name LIKE ? OR s.matric_number LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if(in_array($pt,validProgrammeTypes(),true)){$cond.=' AND s.programme_type=?';$params[]=$pt;}
$project=safeRun($pdo,"SELECT sub.id,sub.file_name,sub.uploaded_at,u.full_name,s.matric_number,s.programme_type,sc.name item_name FROM submissions sub JOIN students s ON s.id=sub.student_id JOIN users u ON u.id=s.user_id JOIN submission_categories sc ON sc.id=sub.category_id WHERE sub.semester_id=? $cond AND sub.id=(SELECT MAX(x.id) FROM submissions x WHERE x.student_id=sub.student_id AND x.category_id=sub.category_id AND x.semester_id=sub.semester_id) ORDER BY sub.uploaded_at DESC",$params)->fetchAll();
$params2=[$currentSemesterId];$cond2='';if($q!==''){$cond2.=' AND (u.full_name LIKE ? OR s.matric_number LIKE ?)';$params2[]='%'.$q.'%';$params2[]='%'.$q.'%';}if(in_array($pt,validProgrammeTypes(),true)){$cond2.=' AND pf.programme_type=?';$params2[]=$pt;}$progress=safeRun($pdo,"SELECT ps.id,ps.file_name,ps.submitted_at,u.full_name,s.matric_number,pf.programme_type,pf.title item_name FROM progress_submissions ps JOIN progress_forms pf ON pf.id=ps.progress_form_id JOIN students s ON s.id=ps.student_id JOIN users u ON u.id=s.user_id WHERE pf.semester_id=? $cond2 ORDER BY ps.submitted_at DESC",$params2)->fetchAll();
?>
<div class="card-fy mb-3"><form method="get" class="row g-2 align-items-end"><input type="hidden" name="view" value="archive"><div class="col-md-6"><label class="form-label small fw-semibold">Student</label><input name="q" value="<?= e($q) ?>" class="form-control-fy w-100" placeholder="Name or matric number"></div><div class="col-md-4"><label class="form-label small fw-semibold">Programme</label><select name="pt" class="form-control-fy w-100"><option value="all">All programmes</option><?php foreach(validProgrammeTypes() as $v): ?><option value="<?= e($v) ?>" <?= $pt===$v?'selected':'' ?>><?= e(programmeTypeLabel($v)) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn-fy-orange w-100">Search</button></div></form></div>
<div class="card-fy mb-3"><div class="section-title">Latest Project Submissions</div><div class="table-responsive"><table class="table-fy"><thead><tr><th>Student</th><th>Category</th><th>Programme</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($project as $r): ?><tr><td><strong><?= e($r['full_name']) ?></strong><div class="small text-muted"><?= e($r['matric_number']) ?></div></td><td><?= e($r['item_name']) ?><div class="small text-muted"><?= e($r['file_name']) ?></div></td><td><?= e(programmeTypeLabel($r['programme_type'])) ?></td><td><?= timeAgo($r['uploaded_at']) ?></td><td><a target="_blank" class="btn-fy-outline btn-sm" href="<?= e(secureFileUrl((int)$r['id'],'submission')) ?>">View</a></td></tr><?php endforeach; ?><?php if(!$project): ?><tr><td colspan="5" class="text-center text-muted py-4">No matching project submissions.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card-fy"><div class="section-title">Progress Form Submissions</div><div class="table-responsive"><table class="table-fy"><thead><tr><th>Student</th><th>Progress Form</th><th>Programme</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($progress as $r): ?><tr><td><strong><?= e($r['full_name']) ?></strong><div class="small text-muted"><?= e($r['matric_number']) ?></div></td><td><?= e($r['item_name']) ?><div class="small text-muted"><?= e($r['file_name']) ?></div></td><td><?= e(programmeTypeLabel($r['programme_type'])) ?></td><td><?= timeAgo($r['submitted_at']) ?></td><td><a target="_blank" class="btn-fy-outline btn-sm" href="<?= e(secureFileUrl((int)$r['id'],'progress_submission')) ?>">View</a></td></tr><?php endforeach; ?><?php if(!$progress): ?><tr><td colspan="5" class="text-center text-muted py-4">No matching progress submissions.</td></tr><?php endif; ?></tbody></table></div></div>
